#!/usr/bin/env node
// Generated by Agent Team Kit 0.16.0. Do not edit.
// merge-gate.sh without bash: the same gate, run by Node. Same arguments, logs, summary and exit codes.
//
//   node scripts/agent-team/merge-gate.mjs <target>...   run the gates for each target
//   node scripts/agent-team/merge-gate.mjs all           run every target in AGENT_TEAM_GATES_ALL
//   node scripts/agent-team/merge-gate.mjs --list        list the targets
//
// Targets come from .agent-team/gates.json ({ "all", "pools", "targets": { name: [{ "name", "run", "pool" }] } }).
// Each step's "run" goes to bash -c when bash is installed (as merge-gate.sh does) and to the system shell otherwise
// (sh, or cmd.exe on Windows); a step with a "pool" holds a with-lock slot while it runs. A target that is only a
// gate_<target> bash function in .agent-team/config.sh needs bash: with bash on the machine this hands the whole run
// to merge-gate.sh; without it, it stops with exit 64 and says to move the target into gates.json.
// Output goes to .merge-gate/<target>-<timestamp>.log; the summary ends with PASS or FAIL lines; exit 1 on any FAIL.
import { execFileSync, spawn, spawnSync } from 'node:child_process';
import { appendFileSync, closeSync, existsSync, mkdirSync, openSync, readFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { shellVars } from './report.mjs';
import { EX_USAGE, acquire, lockSettings } from './with-lock.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const readJson = (f) => { try { return JSON.parse(readFileSync(f, 'utf8')); } catch { return undefined; } };

/** Whether bash can be started on this machine (Git Bash, WSL or a Unix shell). */
export function hasBash(env = process.env) {
  const r = spawnSync('bash', ['-c', 'exit 0'], { env, stdio: 'ignore' });
  return !r.error && r.status === 0;
}

/** The targets a repository defines: from gates.json (run by Node) and gate_<name> functions in config.sh (bash only). */
export function gateTargets(root, env = process.env) {
  const gates = readJson(join(root, '.agent-team/gates.json')) ?? {};
  const configFile = env.AGENT_TEAM_CONFIG || join(root, '.agent-team/config.sh');
  const configText = existsSync(configFile) ? readFileSync(configFile, 'utf8') : '';
  const bashOnly = [...configText.matchAll(/^\s*(?:function\s+)?gate_([A-Za-z0-9_]+)\s*\(\s*\)/gm)].map((m) => m[1]);
  const json = Object.keys(gates.targets ?? {});
  // Like merge-gate.sh: config.sh sets AGENT_TEAM_GATES_ALL, gates.json (gates.sh) replaces it, the environment fills in.
  const all = gates.all?.length ? gates.all.join(' ') : shellVars(configText).AGENT_TEAM_GATES_ALL ?? env.AGENT_TEAM_GATES_ALL ?? '';
  return { gates, json, bashOnly: bashOnly.filter((t) => !json.includes(t)), all };
}

const pad = (n) => String(n).padStart(2, '0');
const stampOf = (d) => `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
const git = (root, args) => { try { return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim(); } catch { return ''; } };

/** Runs one shell step with its output appended to the log; resolves true when it exits 0. */
function runStep(command, log, { root, bash }) {
  return new Promise((resolve) => {
    const fd = openSync(log, 'a');
    const opts = { cwd: root, stdio: ['inherit', fd, fd] };
    const child = bash ? spawn('bash', ['-c', command], opts) : spawn(command, { ...opts, shell: true });
    child.on('error', (e) => { appendFileSync(log, `${e.message}\n`); closeSync(fd); resolve(false); });
    child.on('exit', (code) => { closeSync(fd); resolve(code === 0); });
  });
}

export async function main(argv, env = process.env, out = (s) => process.stdout.write(s), err = (s) => process.stderr.write(s)) {
  const settings = lockSettings(env);
  const root = settings.ctx.root;
  const t = gateTargets(root, env);
  const list = [...t.json, ...t.bashOnly].sort();
  if (!argv.length || argv[0] === '--list' || argv[0] === '-h') {
    err('usage: merge-gate.mjs <target>... | all | --list\n');
    err(`targets: ${list.join(' ')} \n`);
    if (t.bashOnly.length) err(`(bash only, in .agent-team/config.sh: ${t.bashOnly.join(' ')})\n`);
    return argv.length ? 0 : EX_USAGE;
  }
  const want = argv.flatMap((a) => (a === 'all' ? (t.all || list.join(' ')).split(/\s+/).filter(Boolean) : [a]));
  const missing = want.filter((x) => !list.includes(x));
  if (missing.length) { err(`merge-gate: no gate_${missing[0]} in .agent-team/config.sh (targets: ${list.join(' ')} )\n`); return EX_USAGE; }
  const bash = hasBash(env);
  const needBash = want.filter((x) => t.bashOnly.includes(x));
  if (needBash.length) {
    const sh = [join(HERE, 'merge-gate.sh'), join(HERE, '../scripts/merge-gate.sh')].find(existsSync);
    if (!bash || !sh) {
      err(`merge-gate: ${needBash.join(', ')} ${needBash.length === 1 ? 'is a bash function' : 'are bash functions'} in .agent-team/config.sh and this machine has no bash. Move ${needBash.length === 1 ? 'it' : 'them'} into .agent-team/gates.json, or run merge-gate.sh from Git Bash or WSL.\n`);
      return EX_USAGE;
    }
    err(`merge-gate: ${needBash.join(', ')} ${needBash.length === 1 ? 'is a bash function' : 'are bash functions'} in .agent-team/config.sh; running merge-gate.sh\n`);
    const r = spawnSync('bash', [sh, ...argv], { stdio: 'inherit', env });
    return r.status ?? 1;
  }

  mkdirSync(join(root, '.merge-gate'), { recursive: true });
  const stamp = stampOf(new Date());
  const results = [];
  for (const target of want) {
    const log = `.merge-gate/${target}-${stamp}.log`;
    const abs = join(root, log);
    for (const step of t.gates.targets[target] ?? []) {
      const name = `${target}: ${step.name}`;
      out(`== ${name}\n`);
      appendFileSync(abs, `== ${name}\n`);
      let ok;
      if (step.pool) {
        const got = await acquire(step.pool, settings, (s) => appendFileSync(abs, s));
        if (!got.slot) ok = false;
        else {
          appendFileSync(abs, `with-lock: ${step.pool} ${basename(got.slot)} -> ${step.run}\n`);
          try { ok = await runStep(step.run, abs, { root, bash }); } finally { got.release(); }
        }
      } else ok = await runStep(step.run, abs, { root, bash });
      results.push(ok ? `PASS ${name}` : `FAIL ${name} (${log})`);
    }
  }
  out(`\nmerge-gate (${want.join(' ')}) @ ${git(root, ['rev-parse', '--short', 'HEAD']) || '?'} on ${git(root, ['branch', '--show-current']) || '?'}\n`);
  if (!results.length) { out('  (no steps ran)\n'); return 1; }
  for (const r of results) out(`  ${r}\n`);
  return results.some((r) => r.startsWith('FAIL')) ? 1 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).then((code) => { process.exitCode = code; });
}
